-- Stores or replaces E_rec and H_rec of account $1, with the account_key_epoch of the signed state of their commit (CRYPTO.md §11.1 step 8, §11.9 step 6; ADR 0032 §4). Shared by both engines; every value is a bound parameter (INV-53).
INSERT INTO auth_recovery (account_id, recovery_epoch, e_rec, h_rec, updated_at_ms, account_key_epoch) VALUES ($1, $2, $3, $4, $5, $6) ON CONFLICT (account_id) DO UPDATE SET recovery_epoch = excluded.recovery_epoch, e_rec = excluded.e_rec, h_rec = excluded.h_rec, updated_at_ms = excluded.updated_at_ms, account_key_epoch = excluded.account_key_epoch
